"""Summarize two ACTUAL runs only. No predicted/RTL cycles as board performance."""
import hashlib,json,statistics,sys
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1];HERE=ROOT.parent/'model_a_v0_21_1_board_20261013_001'
names=sys.argv[1:] or ['case0000_board001','case0000_board002']
if len(names)!=2 or any(not x.replace('_','').isalnum() for x in names):raise ValueError('Two safe actual run tags required')
target=ROOT/'BOARD_RESULT.json'
if target.exists():raise ValueError('Preserve existing report')
baseline=json.loads((HERE/'BOARD_RESULT.json').read_text());runs=[];outputs=[]
for name in names:
    folder=ROOT/'reports'/name;r=json.loads((folder/'result.json').read_text())
    if not r.get('completed') or not r.get('hardware_executed') or r['cpu_numeric_fallback'] or r['parameter_upload_bytes']!=0:raise ValueError('Actual completed run required '+name)
    backend=r['backend'];plan=backend['plan_counter_delta'];unfused=backend['v021'];core=r['core_hz']
    if plan['closed_plans']!=68 or plan['matrix_descriptors']!=6231 or unfused['native_matrix_tasks']!=593 or plan['last_error']:raise ValueError('Incomplete schedule/counter coverage')
    matrix_pe=(plan['matrix_pe_cycles']+unfused['compute_cycles'])/core;matrix_queue=(plan['matrix_queue_cycles']+unfused['queue_cycles'])/core
    metrics=dict(name=name,elapsed_seconds=r['elapsed_seconds'],encoder_seconds=r['stages']['encoder']['seconds'],decoder_seconds=r['stages']['decoder']['seconds'],all_matrix_pe_seconds=matrix_pe,all_matrix_queue_seconds=matrix_queue,matrix_queue_non_pe_residual_seconds=matrix_queue-matrix_pe,closed_plan=plan,unfused=unfused,fused_boundary_input_bytes=backend['fused_subgraphs']['input_bytes'],fused_boundary_output_bytes=backend['fused_subgraphs']['output_bytes'],fused_boundary_upload_seconds=backend['fused_subgraphs']['upload_seconds'],fused_boundary_download_seconds=backend['fused_subgraphs']['read_seconds'],fused_board_wait_seconds=backend['fused_subgraphs']['board_wait_seconds'],fused_wall_seconds=backend['fused_subgraphs']['wall_seconds'],vs_v21_hardware=r['vs_v21_hardware'],vs_7bit_onnx=r['vs_7bit_onnx'],ethernet=backend.get('ethernet',{}),parameter_generation=r['parameter_generation'],parameter_upload_bytes=0)
    runs.append(metrics);outputs.append(dict(np.load(folder/'hardware_outputs.npz')))
repeat=all(np.array_equal(outputs[0][k].view('u1'),outputs[1][k].view('u1')) for k in outputs[0])
oldmean=statistics.mean(r['elapsed_seconds'] for r in baseline['runs']);mean=statistics.mean(r['elapsed_seconds'] for r in runs);v21=baseline['runs'][0]['vs_v21']['old_seconds']
result=dict(version='V0.22 phase1',hardware_executed=True,cpu_numeric_fallback=False,parameter_load_included_in_case_time=False,runs=runs,repeat_bit_exact=repeat,vs_v211=dict(previous_mean_seconds=oldmean,new_mean_seconds=mean,speed_ratio=oldmean/mean,wall_reduction_percent=(1-mean/oldmean)*100),vs_v21=dict(previous_seconds=v21,new_mean_seconds=mean,speed_ratio=v21/mean,wall_reduction_percent=(1-mean/v21)*100),scope='CASE0000 128features/16suppliedprefix tokens.68closedCONV/FFN PL plans/DDR intermediate arithmetic/layout. OuterDAG stillhost, nofreefirsttoken/CTC/WER. Phase1 integerPE storage stillserial, not yet A/Wprefetch/postedCwriteback.',encoding=baseline['encoding'],data_paths=['ClosedCONV/FFN: DRAM plan -> PL layout/im2col -> matrixHP0 -> C48DDR -> PL FP32/FMA/QDQ dualDMA -> intermediateDDR. PS only planstart/completion/error, no perinternalmatrix queries or payload copying.','Vector operands/output use ping-pong with separate read/writeDMA. Layout readcache64lines andbyte-maskedwritecombining. Depthwise epilogue only validM elements, avoids padded1024 floatconversion pergroup.','Outside closedplans: originalhostDAG/boundaryUDP and legacySRAM nonmatrix path remain. IntegerA/W/C DMA is stillserial.'],timing_scope='Queue includes PE, DMA, stalls andcontrol; queue-minus-PE is a residual, NOT isolated pureDMA. Vector/layout cycles include DDR/operator overhead. Wholeplan andhostnetwork/fusedwait include other intervals: do not add them as disjoint times.',evidence_sha256={str((ROOT/'reports'/name/'result.json').relative_to(ROOT)):hashlib.sha256((ROOT/'reports'/name/'result.json').read_bytes()).hexdigest() for name in names})
target.write_text(json.dumps(result,indent=2,allow_nan=False)+'\n',encoding='utf-8')
exact=all(c['bit_exact'] for r in runs for c in r['vs_v21_hardware'].values())
lines=['V0.22 第一阶段实板结果（非仿真速度）',f"两次 CASE0000：{runs[0]['elapsed_seconds']:.6f}s / {runs[1]['elapsed_seconds']:.6f}s；平均 {mean:.6f}s。",f'参数装载不计入运行；两次运行参数上传均0B。',f'相对 V0.21.1 ASYNC002 平均 {oldmean:.6f}s：{oldmean/mean:.3f}倍，耗时减少{(1-mean/oldmean)*100:.2f}%。',f'相对 V0.21 {v21:.6f}s：{v21/mean:.3f}倍，耗时减少{(1-mean/v21)*100:.2f}%。',f'两次输出逐位一致：{repeat}；与 V0.21 实板输出逐位一致：{exact}。','严格 ONNX 对照单独见 JSON，不以V21逐位一致代替ONNX精度通过。','']
for r in runs:
    p=r['closed_plan'];lines.extend([r['name'],f"Encoder {r['encoder_seconds']:.6f}s，Decoder {r['decoder_seconds']:.6f}s。",f"全部矩阵：PE {r['all_matrix_pe_seconds']:.9f}s；矩阵队列（含PE、DMA、等待）{r['all_matrix_queue_seconds']:.9f}s；非PE残差{r['matrix_queue_non_pe_residual_seconds']:.9f}s，不等于纯DMA。",f"68个PL计划：总{p['whole_plan_seconds']:.9f}s；DDR数值通路{p['vector_seconds']:.9f}s；PL布局{p['layout_seconds']:.9f}s；计划取指{p['plan_fetch_seconds']:.9f}s（包含关系不相加）。",f"非矩阵/布局DMA真实读{p['vector_layout_read_bytes']}B，写{p['vector_layout_write_bytes']}B（不含矩阵DMA）。",f"闭合子图边界UDP：上传{r['fused_boundary_input_bytes']}B/{r['fused_boundary_upload_seconds']:.6f}s；下载{r['fused_boundary_output_bytes']}B/{r['fused_boundary_download_seconds']:.6f}s。",''])
lines.extend(['已上板：PL计划、直接DDR CONV/FFN数值链、PL im2col/布局、系数复用、depthwise有效输出紧凑尾处理。','尚未上板：整数矩阵A/W预取与C写回重叠、完整外层DAG自治、进一步depthwise批处理和MNK驻留改造。','数据路径和详细计数见 BOARD_RESULT.json。原封存代码、参数、历史板测文件未改。'])
(ROOT/'BOARD_RESULT_zh.txt').write_text('\n'.join(lines)+'\n',encoding='utf-8');print('\n'.join(lines[:7]))
